use std::{collections::HashMap, path::{Path, PathBuf}, sync::{Arc, Mutex, atomic::AtomicBool}};
use serde::Serialize;
use tauri::{AppHandle, Emitter, Manager, State};
use baconconsole::{catalog::{Catalog, CatalogGame, InstallationInput, UserProfile}, disc::{load_manifest, manifest_total_bytes, BaconManifest}, emulators::{list_profiles, retroarch_arguments, save_profile, validate_profile, EmulatorKind, EmulatorProfile, Platform}, launcher::{GameLauncher, LaunchRequest, NativeProcessRunner}, library::{list_installs, register_install, LibraryRecord}, storage::{available_space, copy_verified_with, verify_manifest_files, CopyOptions, CopyProgress}};

pub struct CopyJobs(pub Mutex<HashMap<String, Arc<AtomicBool>>>);
pub struct NativeLauncher(pub GameLauncher<NativeProcessRunner>);
fn catalog(app:&AppHandle)->Result<Catalog,String> { let root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library"); Catalog::open(&root) }
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiscSummary { pub id: String, pub title: String, pub platform: String, pub package_type: String, pub entry_point: String, pub modes: Vec<String>, pub file_count: usize, pub total_bytes: u64 }
impl TryFrom<(BaconManifest, PathBuf)> for DiscSummary { type Error = String; fn try_from((value, root): (BaconManifest, PathBuf)) -> Result<Self, Self::Error> { let total_bytes = manifest_total_bytes(&root).map_err(|error| error.to_string())?; Ok(Self { id:value.id, title:value.title, platform:value.platform, package_type:value.package_type, entry_point:value.entry_point, modes:value.modes, file_count:value.files.len(), total_bytes }) } }
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct StorageTarget { pub kind: String, pub root: String, pub available_bytes: u64 }
#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CopyProgressEvent { pub job_id: String, pub copied_bytes: u64, pub total_bytes: u64, pub completed_files: usize, pub file_count: usize }
impl CopyProgressEvent { fn from_progress(job_id: String, progress: CopyProgress) -> Self { Self { job_id, copied_bytes: progress.copied_bytes, total_bytes: progress.total_bytes, completed_files: progress.completed_files, file_count: progress.file_count } } }

#[tauri::command] pub fn inspect_simulated_disc(root: String) -> Result<DiscSummary, String> { let root = PathBuf::from(root); load_manifest(&root).map_err(|error| error.to_string()).and_then(|manifest| DiscSummary::try_from((manifest, root))) }
#[tauri::command] pub fn verify_simulated_disc(root: String) -> Result<u64, String> { verify_manifest_files(&PathBuf::from(root)).map_err(|error| error.to_string()) }
#[tauri::command] pub fn copy_simulated_disc(root: String, destination: String) -> Result<u64, String> { baconconsole::storage::copy_verified(&PathBuf::from(root), &PathBuf::from(destination)).map_err(|error| error.to_string()) }
#[tauri::command] pub fn get_storage_targets(app: AppHandle) -> Result<Vec<StorageTarget>, String> { let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("storage"); std::fs::create_dir_all(&root).map_err(|error| error.to_string())?; let available_bytes = available_space(&root).map_err(|error| error.to_string())?; Ok(vec![StorageTarget { kind: "ssd".into(), root: root.to_string_lossy().to_string(), available_bytes }]) }
#[tauri::command] pub fn start_verified_copy(app: AppHandle, jobs: State<CopyJobs>, job_id: String, root: String, destination: String, target_kind: String) -> Result<u64, String> {
    let flag = Arc::new(AtomicBool::new(false)); jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.insert(job_id.clone(), flag.clone());
    let destination_path = PathBuf::from(&destination); let available = available_space(&destination_path).map_err(|error| error.to_string())?;
    let result = copy_verified_with(&PathBuf::from(&root), &destination_path, CopyOptions::with_available_space_and_cancel(available, flag), |progress| { let _ = app.emit("bacondisc-copy-progress", CopyProgressEvent::from_progress(job_id.clone(), progress)); }).map_err(|error| error.to_string());
    jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.remove(&job_id); let copied = result?;
    if target_kind == "permanent" { let manifest = load_manifest(&PathBuf::from(root)).map_err(|error| error.to_string())?; let library_root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("library"); register_install(&library_root, LibraryRecord::permanent(manifest.id.clone(), manifest.title.clone(), destination.clone(), true)).map_err(|error| error.to_string())?; catalog(&app)?.upsert_installation(InstallationInput::new(format!("bacondisc:{}",manifest.id),manifest.title,manifest.platform,"ssd",destination,true))?; }
    Ok(copied)
}
#[tauri::command] pub fn cancel_copy(jobs: State<CopyJobs>, job_id: String) -> Result<(), String> { if let Some(flag) = jobs.0.lock().map_err(|_| "copy job state unavailable".to_string())?.get(&job_id) { flag.store(true, std::sync::atomic::Ordering::Relaxed); } Ok(()) }
#[tauri::command] pub fn list_library_records(app: AppHandle) -> Result<Vec<LibraryRecord>, String> { let library_root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("library"); list_installs(&library_root).map_err(|error| error.to_string()) }
#[tauri::command] pub fn list_catalog_games(app:AppHandle)->Result<Vec<CatalogGame>,String>{ catalog(&app)?.list_games() }
#[tauri::command] pub fn list_local_users(app:AppHandle)->Result<Vec<UserProfile>,String>{ catalog(&app)?.list_users() }
#[tauri::command] pub fn get_active_local_user(app:AppHandle)->Result<UserProfile,String>{ catalog(&app)?.active_user() }
#[tauri::command] pub fn create_local_user(app:AppHandle,name:String,avatar:Option<String>)->Result<UserProfile,String>{ let name=name.trim(); if name.is_empty() || name.len()>32 { return Err("nome de perfil inválido".into()) }; catalog(&app)?.create_user(name,avatar.as_deref()) }
#[tauri::command] pub fn set_active_local_user(app:AppHandle,user_id:i64)->Result<(),String>{ catalog(&app)?.set_active_user(user_id) }
#[tauri::command] pub fn toggle_catalog_favorite(app:AppHandle,game_id:i64)->Result<bool,String>{ let store=catalog(&app)?; let user=store.active_user()?; store.toggle_favorite(user.id,game_id)?; store.is_favorite(user.id,game_id) }
#[tauri::command] pub fn list_emulator_profiles(app: AppHandle) -> Result<Vec<EmulatorProfile>, String> { let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("emulators"); list_profiles(&root).map_err(|error| error.to_string()) }
#[tauri::command] pub fn bundled_emulator_profiles() -> Vec<EmulatorProfile> { let base = std::env::var_os("LOCALAPPDATA").map(PathBuf::from).unwrap_or_default().join("BaconConsole").join("tools"); let retro_root = base.join("RetroArch").join("RetroArch-Win64"); let mut retroarch = EmulatorProfile::new("retroarch", "RetroArch", EmulatorKind::RetroArch, retro_root.join("retroarch.exe").to_string_lossy()); for (platform, core) in [(Platform::Nes, "fceumm_libretro.dll"), (Platform::Snes, "snes9x_libretro.dll"), (Platform::Megadrive, "genesis_plus_gx_libretro.dll"), (Platform::Gba, "mgba_libretro.dll")] { retroarch.cores.insert(platform, retro_root.join("cores").join(core).to_string_lossy().to_string()); } vec![retroarch, EmulatorProfile::new("duckstation", "DuckStation", EmulatorKind::Duckstation, base.join("DuckStation").join("duckstation-qt-x64-ReleaseLTCG.exe").to_string_lossy()), EmulatorProfile::new("pcsx2", "PCSX2", EmulatorKind::Pcsx2, base.join("PCSX2").join("pcsx2-qt.exe").to_string_lossy()), EmulatorProfile::new("windows-portable", "Windows portátil", EmulatorKind::WindowsPortable, "")].into_iter().filter(|profile| validate_profile(profile).is_ok()).collect() }
#[tauri::command] pub fn save_emulator_profile(app: AppHandle, profile: EmulatorProfile) -> Result<(), String> { validate_profile(&profile).map_err(|error| error.to_string())?; let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("emulators"); save_profile(&root, profile).map_err(|error| error.to_string()) }
fn platform(value: &str) -> Result<Platform, String> { match value { "nes" => Ok(Platform::Nes), "snes" => Ok(Platform::Snes), "megadrive" => Ok(Platform::Megadrive), "gba" => Ok(Platform::Gba), "ps1" => Ok(Platform::Ps1), "ps2" => Ok(Platform::Ps2), "windows" => Ok(Platform::Windows), _ => Err("plataforma não suportada".into()) } }
fn validated_content(root: &str, relative: &str) -> Result<PathBuf, String> { let root = Path::new(root).canonicalize().map_err(|_| "raiz de conteúdo inválida".to_string())?; let relative = Path::new(relative); if relative.is_absolute() || relative.components().any(|component| matches!(component, std::path::Component::ParentDir | std::path::Component::Prefix(_) | std::path::Component::RootDir)) { return Err("caminho de conteúdo inseguro".into()); } let content = root.join(relative).canonicalize().map_err(|_| "conteúdo não encontrado".to_string())?; if !content.starts_with(&root) || !content.is_file() { return Err("conteúdo fora da raiz permitida".into()); } Ok(content) }
#[tauri::command] pub fn launch_game(app: AppHandle, launcher: State<NativeLauncher>, profile_id: String, content_root: String, content_relative: String, content_platform: String) -> Result<(), String> { let root = app.path().app_data_dir().map_err(|error| error.to_string())?.join("emulators"); let profile = list_profiles(&root).map_err(|error| error.to_string())?.into_iter().find(|profile| profile.id == profile_id).or_else(|| bundled_emulator_profiles().into_iter().find(|profile| profile.id == profile_id)).ok_or("perfil de emulador não encontrado")?; validate_profile(&profile).map_err(|error| error.to_string())?; let content = validated_content(&content_root, &content_relative)?; let selected_platform = platform(&content_platform)?; let request = match profile.kind { EmulatorKind::RetroArch => LaunchRequest::new(&profile.executable, retroarch_arguments(&profile, selected_platform, &content).map_err(|error| error.to_string())?.into_iter().map(|argument| argument.to_string_lossy().to_string()).collect()), EmulatorKind::Duckstation | EmulatorKind::Pcsx2 => LaunchRequest::new(&profile.executable, vec![content.to_string_lossy().to_string()]), EmulatorKind::WindowsPortable => { if !content.extension().is_some_and(|extension| extension.eq_ignore_ascii_case("exe")) { return Err("jogos portáteis devem apontar para um .exe".into()); } LaunchRequest::new(content.clone(), Vec::new()) } }; let store=catalog(&app)?; let identity=format!("portable:{}",content.to_string_lossy().to_lowercase()); let title=content.file_stem().and_then(|value|value.to_str()).unwrap_or("Conteúdo local").to_owned(); store.upsert_installation(InstallationInput::new(identity.clone(),title,content_platform,"local",content.to_string_lossy(),false))?; let user=store.active_user()?; let session=store.game_id_for_identity(&identity)?.and_then(|game|store.start_play_session(user.id,game).ok()); let library_root=app.path().app_data_dir().map_err(|error|error.to_string())?.join("library"); let launcher = launcher.0.clone(); std::thread::spawn(move || { let started=std::time::Instant::now(); let _ = app.emit("baconconsole-launch-state", "running"); let result = launcher.launch(request); if let Some(session_id)=session { let _=Catalog::open(&library_root).and_then(|store|store.finish_play_session(session_id,started.elapsed().as_secs() as i64)); } let _ = app.emit("baconconsole-launch-state", if result.is_ok() { "returned" } else { "failed" }); }); Ok(()) }
